interface FlavorIconProps {
  slug: string;
  className?: string;
}

export function FlavorIcon({ slug, className }: FlavorIconProps) {
  const entry = FLAVOR_PATH_MAP[slug as FlavorSlug];
  if (!entry) return null;
  return (
    <svg
      viewBox="0 0 24 24"
      fill={entry.stroke ? "none" : "currentColor"}
      stroke={entry.stroke ? "currentColor" : "none"}
      strokeWidth={entry.stroke ? 1.5 : undefined}
      strokeLinecap={entry.stroke ? "round" : undefined}
      strokeLinejoin={entry.stroke ? "round" : undefined}
      className={cn("h-4 w-4 shrink-0", className)}
      aria-hidden="true"
    >
      {entry.paths}
    </svg>
  );
}

